def weekly_aov(daily):
    """daily: list of (week, region, revenue, orders) rows, one per day.
    Return {(week, region): average order value for that week}, or None where there were no orders."""
    groups = {}
    for week, region, revenue, orders in daily:
        groups.setdefault((week, region), []).append(revenue / orders if orders else 0)
    return {k: sum(v) / len(v) for k, v in groups.items()}

